 const p=make(id,'<div class="a-columns">'+panel('Địa chỉ & subnet',field('vt-subnet-ip','IPv4 hoặc CIDR','192.168.1.10')+field('vt-subnet-mask','Prefix hoặc subnet mask','24')+'<div class="a-toolbar"><button class="a-primary v-run">Tính subnet</button><button class="v-example">Dùng ví dụ /24</button></div><p class="a-hint">Ví dụ: 192.168.1.10 với 24, /24 hoặc 255.255.255.0. Nếu nhập CIDR trong ô IPv4, prefix trong CIDR được ưu tiên. Chỉ hỗ trợ IPv4, không thực hiện quét mạng.</p>')+panel('Thông tin mạng','<div class="v-subnet-details"></div><p class="v-subnet-note a-summary"></p>')+'</div>'+panel('Báo cáo JSON',ta('vt-subnet-output','Kết quả subnet')+outputButtons));let result='';q(p,'#vt-subnet-output').readOnly=true;const clear=()=>{result='';invalidate(p,'#vt-subnet-output');q(p,'.v-subnet-details').replaceChildren();q(p,'.v-subnet-note').textContent=''};const run=()=>{clear();try{const r=C.subnet(q(p,'#vt-subnet-ip').value,q(p,'#vt-subnet-mask').value);result=JSON.stringify(r,null,2);q(p,'#vt-subnet-output').value=result;keyValues(q(p,'.v-subnet-details'),[['IPv4',r.ip],['Mạng CIDR',r.cidr],['Subnet mask',r.netmask],['Wildcard mask',r.wildcard],['Địa chỉ mạng',r.network],['Broadcast',r.broadcast],['Host đầu',r.firstHost],['Host cuối',r.lastHost],['Tổng địa chỉ',r.total.toLocaleString('vi-VN')],['Địa chỉ host dùng được',r.usable.toLocaleString('vi-VN')]]);q(p,'.v-subnet-note').textContent=r.note;ready(p,true);status(p,'Đã tính subnet IPv4.')}catch(e){status(p,e.message,true)}};q(p,'.v-run').onclick=run;q(p,'.v-example').onclick=()=>{q(p,'#vt-subnet-ip').value='192.168.1.10';q(p,'#vt-subnet-mask').value='24';run()};p.querySelectorAll('input').forEach(el=>el.oninput=clear);outputActions(p,()=>result,'toolhub-subnet.json','application/json');run();return p;
