if(id==='urlextract'){
 const p=make(id,'<div class="a-toolbar">'+check('vt-extract-unique','Lọc URL trùng',true)+check('vt-extract-sort','Sắp xếp A–Z')+check('vt-extract-tracking','Bỏ utm_*, fbclid, gclid, msclkid, dclid')+check('vt-extract-fragments','Giữ fragment (#)',true)+'</div><div class="a-columns">'+panel('Nội dung nguồn',ta('vt-extract-input','Văn bản chứa URL')+'<p class="a-hint">Tối đa 500.000 ký tự, 5.000 URL. Chỉ lấy liên kết đầy đủ http:// hoặc https://. Loại dấu câu bao quanh theo quy tắc văn bản thông thường; hãy kiểm tra URL có dấu câu đặc biệt. Công cụ không mở liên kết.</p>')+panel('Danh sách URL',ta('vt-extract-output','Mỗi dòng một URL')+'<p class="v-extract-summary a-summary">Chưa có kết quả.</p>'+outputButtons)+'</div><div class="a-toolbar"><button class="a-primary v-run">Trích xuất URL</button><button class="v-example">Dùng ví dụ</button><button class="v-clear">Xóa</button></div>');let result='';q(p,'#vt-extract-output').readOnly=true;const clear=()=>{result='';invalidate(p,'#vt-extract-output');q(p,'.v-extract-summary').textContent='Chưa có kết quả mới.'};const run=()=>{clear();try{const r=C.extractURLs(q(p,'#vt-extract-input').value,{unique:q(p,'#vt-extract-unique').checked,sort:q(p,'#vt-extract-sort').checked,stripTracking:q(p,'#vt-extract-tracking').checked,fragments:q(p,'#vt-extract-fragments').checked});result=r.text;q(p,'#vt-extract-output').value=result;q(p,'.v-extract-summary').textContent=`${r.found} URL hợp lệ · ${r.count} URL kết quả${r.invalid?' · bỏ qua '+r.invalid+' URL lỗi':''}`;ready(p,!!r.count);status(p,r.count?'Đã trích xuất URL.':'Không tìm thấy URL HTTP/HTTPS hợp lệ.')}catch(e){status(p,e.message,true)}};q(p,'.v-run').onclick=run;q(p,'.v-example').onclick=()=>{q(p,'#vt-extract-input').value='Tài liệu: https://example.com/docs?utm_source=newsletter#intro\nLiên kết lặp: https://example.com/docs?utm_source=newsletter#intro\nTrang chủ: (https://example.org/).\nCó ngoặc: https://example.com/wiki/Function_(math)';run()};q(p,'.v-clear').onclick=()=>{q(p,'#vt-extract-input').value='';clear()};p.querySelectorAll('input,textarea:not(#vt-extract-output)').forEach(el=>el.oninput=clear);outputActions(p,()=>result,'toolhub-urls.txt');return p;
}
